#!/usr/bin/env bash
set -Eeuo pipefail
cd "$HOME/Downloads"

DEV="${TSP_DEV:-root@192.168.1.25}"
CTR="${TSP_BUILDER:-openmw_builder}"

ROOT="/mnt/SDCARD/data/ports/openmw51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
BASE="$MOD/scripts/TSPInteriorVisGrid"
LIVE_LUA="$BASE/visgrid.lua"
INTERIORMAP="$BASE/interiormap.lua"
TOPOLOGY="$BASE/topology.lua"
TOPOLOGY_CELLS="$BASE/topology_cells"
DB="/mnt/UDISK/openmw51-nav/navmesh.db"
GAME="$ROOT/bin/openmw-0.51"

EXPECTED_V20_SHA="2ef92caeb5f8cdc8c95251aaa7fbe6332939a7cce6f242b752f6901c16becd9b"
EXPECTED_V21_SHA="d41fd6e77765aa0fa1c468027400501d0e83eb284068b26340078026a0f35150"

STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/openmw51-visgrid-v21-$STAMP"
PKG="$OUT/pkg"
LOG="$OUT/controller.log"
mkdir -p "$PKG"

exec > >(tee "$LOG") 2>&1

echo "=================================================================="
echo "OPENMW 0.51 — VISGRID V21 REAL DOORS + VIEW-WITNESS MEMORY"
echo "=================================================================="
echo "This revision:"
echo "  - keeps the proven 1321-cell global topology unchanged"
echo "  - overlays real ESM/ESP door locations and WORLD_EXIT metadata"
echo "  - upgrades local static portals to real doors when safely matched"
echo "  - keeps positive narrow-opening rays rendered while still in view"
echo "  - releases them after 3 close confirmations or a real view-away"
echo "  - live ray evidence overrides vertical/Z caps for held openings"
echo
echo "No OpenMW-running process gate is used."
echo "If the game is currently open, restart it after installation."
echo "=================================================================="

echo
echo "===== 1/8 LOCATE EXISTING REAL DOOR GRAPH ====="

DOOR_TSV="${TSP_DOOR_GRAPH:-}"
if [ -n "$DOOR_TSV" ] && [ ! -s "$DOOR_TSV" ]; then
    echo "ERROR: TSP_DOOR_GRAPH was set but is not a readable file:"
    echo "  $DOOR_TSV"
    exit 10
fi

if [ -z "$DOOR_TSV" ]; then
    DOOR_TSV="$(
        find "$HOME/Downloads" -maxdepth 4 -type f -name 'door_graph.tsv' \
            -path '*/openmw51-global-map-*/*' \
            -printf '%T@\t%p\n' 2>/dev/null |
        sort -nr |
        head -1 |
        cut -f2-
    )"
fi

if [ -z "$DOOR_TSV" ]; then
    MAP_TAR="$(
        find "$HOME/Downloads" -maxdepth 2 -type f \
            -name 'openmw51-global-map-*.tar.gz' \
            -printf '%T@\t%p\n' 2>/dev/null |
        sort -nr |
        head -1 |
        cut -f2-
    )"
    if [ -n "$MAP_TAR" ]; then
        MEMBER="$(tar -tzf "$MAP_TAR" | grep -E '(^|/)door_graph\.tsv$' | head -1 || true)"
        if [ -n "$MEMBER" ]; then
            tar -xOzf "$MAP_TAR" "$MEMBER" > "$OUT/door_graph.tsv"
            DOOR_TSV="$OUT/door_graph.tsv"
            echo "Recovered door graph from:"
            echo "  $MAP_TAR"
        fi
    fi
fi

[ -s "$DOOR_TSV" ] || {
    echo "ERROR: existing door_graph.tsv was not found."
    echo "Expected under an earlier ~/Downloads/openmw51-global-map-* output"
    echo "or archive. Nothing was changed."
    exit 11
}

echo "Door graph:"
echo "  $DOOR_TSV"
sha256sum "$DOOR_TSV"
echo "rows=$(($(wc -l < "$DOOR_TSV") - 1))"

echo
echo "===== 2/8 VERIFY CURRENT DEVICE BASELINE ====="

ssh "$DEV" "
set -e
test -s '$LIVE_LUA'
test -s '$INTERIORMAP'
test -s '$TOPOLOGY'
test -d '$TOPOLOGY_CELLS'
test -s '$GAME'
test -s '$DB'
grep -q 'TSP_VISGRID_GLOBAL_TOPOLOGY_V1' '$TOPOLOGY'
"

scp -q "$DEV:$LIVE_LUA" "$OUT/visgrid-live.lua"
scp -q "$DEV:$INTERIORMAP" "$OUT/interiormap.lua"

LIVE_SHA="$(sha256sum "$OUT/visgrid-live.lua" | awk '{print $1}')"
echo "Live sensor SHA: $LIVE_SHA"

if grep -Fq 'TSP_VISGRID_LUA_V21_DOORGRAPH_VIEWHOLD' "$OUT/visgrid-live.lua"; then
    echo "V21 is already installed. No changes made."
    exit 0
fi

[ "$LIVE_SHA" = "$EXPECTED_V20_SHA" ] || {
    echo "ERROR: live sensor is not the exact proven V20 source."
    echo "Expected: $EXPECTED_V20_SHA"
    echo "Got:      $LIVE_SHA"
    echo "Nothing was changed."
    exit 12
}

GAME_SHA_BEFORE="$(ssh "$DEV" "sha256sum '$GAME'" | awk '{print $1}')"
TOPO_SHA_BEFORE="$(ssh "$DEV" "sha256sum '$TOPOLOGY'" | awk '{print $1}')"
DB_STAT_BEFORE="$(ssh "$DEV" "stat -c '%s %Y' '$DB'")"
SHARDS_BEFORE="$(ssh "$DEV" "find '$TOPOLOGY_CELLS' -type f -name '*.lua' | wc -l")"

echo "game SHA:       $GAME_SHA_BEFORE"
echo "topology SHA:   $TOPO_SHA_BEFORE"
echo "DB size/mtime:  $DB_STAT_BEFORE"
echo "topology shards=$SHARDS_BEFORE"

[ "$SHARDS_BEFORE" -eq 1321 ] || {
    echo "ERROR: expected the proven 1321 installed topology shards."
    exit 13
}

echo
echo "===== 3/8 BUILD LAZY REAL-DOOR SIDECAR ====="

base64 -d > "$OUT/build_doorgraph.py" <<'B64_DOORS'

B64_DOORS

python3 "$OUT/build_doorgraph.py" \
    "$DOOR_TSV" \
    "$OUT/interiormap.lua" \
    "$PKG"

cat "$PKG/DOORGRAPH-SUMMARY.txt"

DOOR_CELLS="$(find "$PKG/doorgraph_cells" -type f -name '*.lua' | wc -l)"
DOOR_REFS="$(awk -F= '/^interior_door_refs=/{print $2}' "$PKG/DOORGRAPH-SUMMARY.txt")"

[ "$DOOR_CELLS" -gt 100 ] || {
    echo "ERROR: unexpectedly few interior door cells: $DOOR_CELLS"
    exit 14
}
[ "${DOOR_REFS:-0}" -gt 100 ] || {
    echo "ERROR: unexpectedly few interior door refs: ${DOOR_REFS:-0}"
    exit 15
}

echo "PASS: lazy real-door graph built."

echo
echo "===== 4/8 GENERATE EXACT V21 SENSOR FROM EXACT V20 ====="

base64 -d > "$OUT/patch_v21.py" <<'B64_PATCH'

B64_PATCH

python3 "$OUT/patch_v21.py" \
    "$OUT/visgrid-live.lua" \
    "$PKG/visgrid.lua"

V21_SHA="$(sha256sum "$PKG/visgrid.lua" | awk '{print $1}')"
echo "V21 sensor SHA: $V21_SHA"

[ "$V21_SHA" = "$EXPECTED_V21_SHA" ]

grep -Fq 'TSP_VISGRID_LUA_V21_DOORGRAPH_VIEWHOLD' "$PKG/visgrid.lua"
grep -Fq 'mapState.rayViewHeldDepth' "$PKG/visgrid.lua"
grep -Fq 'mapState.primeRealDoors' "$PKG/visgrid.lua"
grep -Fq 'TSP_VISGRID_REAL_DOOR_GRAPH_V1' "$PKG/doorgraph.lua"

echo
echo "===== 5/8 LUA PARSE CHECK BEFORE DEVICE INSTALL ====="

PARSED=0
if command -v luac >/dev/null 2>&1; then
    while IFS= read -r -d '' f; do
        luac -p "$f"
    done < <(find "$PKG" -type f -name '*.lua' -print0)
    PARSED=1
    echo "PASS: all V21 Lua parsed with host luac."
elif command -v lua >/dev/null 2>&1; then
    while IFS= read -r -d '' f; do
        lua -e 'local f=arg[1]; local c,e=loadfile(f); if not c then error(e) end' "$f"
    done < <(find "$PKG" -type f -name '*.lua' -print0)
    PARSED=1
    echo "PASS: all V21 Lua parsed with host lua."
else
    docker inspect "$CTR" >/dev/null
    if [ "$(docker inspect -f '{{.State.Running}}' "$CTR")" != "true" ]; then
        docker start "$CTR" >/dev/null
    fi
    DCHECK="/root/tsp-v21-parse-$STAMP"
    docker exec "$CTR" rm -rf "$DCHECK"
    docker exec "$CTR" mkdir -p "$DCHECK"
    docker cp "$PKG/." "$CTR:$DCHECK/"
    if docker exec "$CTR" bash -lc 'command -v luajit >/dev/null 2>&1'; then
        docker exec "$CTR" bash -lc "
set -e
find '$DCHECK' -type f -name '*.lua' -print0 |
while IFS= read -r -d '' f; do
    luajit -b "\$f" /tmp/tsp-v21-check.luac
done
rm -f /tmp/tsp-v21-check.luac
"
        PARSED=1
        echo "PASS: all V21 Lua parsed with Docker LuaJIT."
    elif docker exec "$CTR" bash -lc 'command -v lua >/dev/null 2>&1'; then
        docker exec "$CTR" bash -lc "
set -e
find '$DCHECK' -type f -name '*.lua' -print0 |
while IFS= read -r -d '' f; do
    lua -e 'local f=arg[1]; local c,e=loadfile(f); if not c then error(e) end' "\$f"
done
"
        PARSED=1
        echo "PASS: all V21 Lua parsed with Docker lua."
    fi
    docker exec "$CTR" rm -rf "$DCHECK"
fi

if [ "$PARSED" -ne 1 ]; then
    echo "NOTE: no Lua CLI parser is installed on this VM/container."
    echo "Using exact-SHA V21 validation + strict generated-doorgraph validation."

    [ "$V21_SHA" = "$EXPECTED_V21_SHA" ] || {
        echo "ERROR: V21 bytes differ from the independently parse-validated reference."
        exit 16
    }

    python3 - "$PKG" "$DOOR_CELLS" "$DOOR_REFS" <<'PY_SIDECAR_GATE'
from pathlib import Path
import sys

pkg = Path(sys.argv[1])
expected_cells = int(sys.argv[2])
expected_refs = int(sys.argv[3])

loader = pkg / "doorgraph.lua"
cells_dir = pkg / "doorgraph_cells"

if not loader.is_file():
    raise SystemExit(
        f"ERROR: generated doorgraph loader missing: {loader}"
    )

if not cells_dir.is_dir():
    raise SystemExit(
        f"ERROR: generated doorgraph_cells missing: {cells_dir}"
    )

loader_raw = loader.read_bytes()

if 0 in loader_raw:
    raise SystemExit(
        "ERROR: NUL byte in generated doorgraph.lua"
    )

loader_text = loader_raw.decode(
    "utf-8",
    "strict",
)

required_loader_tokens = (
    "TSP_VISGRID_REAL_DOOR_GRAPH_V1",
    "local T = {",
    "local index = {",
    "setmetatable(T.cells",
    "function T.getCell(name)",
    "return T",
)

for token in required_loader_tokens:
    if token not in loader_text:
        raise SystemExit(
            "ERROR: doorgraph loader missing "
            + repr(token)
        )

shards = sorted(
    cells_dir.glob("*.lua")
)

if len(shards) != expected_cells:
    raise SystemExit(
        f"ERROR: expected {expected_cells} doorgraph shards, "
        f"found {len(shards)}"
    )

required_entry_fields = (
    "id=",
    ",refnum=",
    ",x=",
    ",y=",
    ",z=",
    ",teleport=",
    ",destKind=",
    ",destCell=",
    ",destX=",
    ",destY=",
    ",destZ=",
    ",content=",
    ",loadIndex=",
)

refs = 0

for shard in shards:
    raw = shard.read_bytes()

    if 0 in raw:
        raise SystemExit(
            f"ERROR: NUL byte in {shard}"
        )

    for byte in raw:
        if byte < 32 and byte not in (9, 10, 13):
            raise SystemExit(
                f"ERROR: unexpected control byte "
                f"{byte} in {shard}"
            )

    lines = raw.decode(
        "utf-8",
        "strict",
    ).splitlines()

    if len(lines) < 3:
        raise SystemExit(
            f"ERROR: truncated doorgraph shard {shard}"
        )

    if lines[0].strip() != \
            "-- TSP_VISGRID_REAL_DOOR_CELL_V1":
        raise SystemExit(
            f"ERROR: bad shard marker in {shard}"
        )

    if lines[1].strip() != "return {":
        raise SystemExit(
            f"ERROR: bad shard opening in {shard}"
        )

    if lines[-1].strip() != "}":
        raise SystemExit(
            f"ERROR: bad shard closing in {shard}"
        )

    for line_no, line in enumerate(
        lines[2:-1],
        3,
    ):
        entry = line.strip()

        if not entry:
            continue

        if not entry.startswith("{id="):
            raise SystemExit(
                f"ERROR: malformed door entry start "
                f"in {shard}:{line_no}: "
                + repr(entry[:180])
            )

        if not entry.endswith("},"):
            raise SystemExit(
                f"ERROR: malformed door entry end "
                f"in {shard}:{line_no}: "
                + repr(entry[:180])
            )

        for field in required_entry_fields:
            if field not in entry:
                raise SystemExit(
                    f"ERROR: missing {field!r} "
                    f"in {shard}:{line_no}"
                )

        if (
            "teleport=true" not in entry
            and
            "teleport=false" not in entry
        ):
            raise SystemExit(
                f"ERROR: invalid teleport field "
                f"in {shard}:{line_no}"
            )

        refs += 1

if refs != expected_refs:
    raise SystemExit(
        f"ERROR: expected {expected_refs} door refs, "
        f"validated {refs}"
    )

print(
    "PASS: validated "
    f"{len(shards)} doorgraph shards / "
    f"{refs} door refs"
)
PY_SIDECAR_GATE

    PARSED=1

    echo "PASS: exact V21 SHA is the independently Lua-parse-validated build."
    echo "PASS: generated real-door sidecars passed strict structural validation."
fi

tar -C "$PKG" -czf "$OUT/v21-runtime.tar.gz" \
    visgrid.lua \
    doorgraph.lua \
    doorgraph_cells \
    DOORGRAPH-SUMMARY.txt

sha256sum "$OUT/v21-runtime.tar.gz"

echo
echo "===== 6/8 INSTALL V21 SIDECARS + SENSOR ====="

scp -q "$OUT/v21-runtime.tar.gz" "$DEV:$ROOT/v21-runtime.tar.gz.new"

ssh "$DEV" "STAMP='$STAMP' bash -s" <<'REMOTE_INSTALL'
set -Eeuo pipefail

ROOT="/mnt/SDCARD/data/ports/openmw51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
BASE="$MOD/scripts/TSPInteriorVisGrid"
ARCHIVE="$ROOT/v21-runtime.tar.gz.new"
STAGE="$MOD/.v21-stage-$STAMP"
BACK="$MOD/v21-backups/$STAMP"

rm -rf "$STAGE"
mkdir -p "$STAGE" "$BACK"
tar -xzf "$ARCHIVE" -C "$STAGE"

test -s "$STAGE/visgrid.lua"
test -s "$STAGE/doorgraph.lua"
test -d "$STAGE/doorgraph_cells"
grep -q 'TSP_VISGRID_LUA_V21_DOORGRAPH_VIEWHOLD' "$STAGE/visgrid.lua"
grep -q 'TSP_VISGRID_REAL_DOOR_GRAPH_V1' "$STAGE/doorgraph.lua"

COUNT="$(find "$STAGE/doorgraph_cells" -type f -name '*.lua' | wc -l)"
[ "$COUNT" -gt 100 ]

cp -p "$BASE/visgrid.lua" "$BACK/visgrid.lua.before"

if [ -s "$BASE/doorgraph.lua" ]; then
    cp -p "$BASE/doorgraph.lua" "$BACK/doorgraph.lua.before"
fi
if [ -d "$BASE/doorgraph_cells" ]; then
    mv "$BASE/doorgraph_cells" "$BACK/doorgraph_cells.before"
fi
if [ -s "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt" ]; then
    cp -p "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt"         "$BACK/REAL-DOOR-GRAPH-SUMMARY.txt.before"
fi

rm -rf "$BASE/doorgraph_cells.new"
mv "$STAGE/doorgraph_cells" "$BASE/doorgraph_cells.new"
cp -p "$STAGE/doorgraph.lua" "$BASE/doorgraph.lua.new"
cp -p "$STAGE/visgrid.lua" "$BASE/visgrid.lua.new"
cp -p "$STAGE/DOORGRAPH-SUMMARY.txt" "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt.new"

sync

mv -f "$BASE/doorgraph.lua.new" "$BASE/doorgraph.lua"
rm -rf "$BASE/doorgraph_cells"
mv "$BASE/doorgraph_cells.new" "$BASE/doorgraph_cells"
mv -f "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt.new" "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt"
mv -f "$BASE/visgrid.lua.new" "$BASE/visgrid.lua"

rm -rf "$STAGE"
rm -f "$ARCHIVE"
sync

echo "Installed V21:"
sha256sum "$BASE/visgrid.lua"
echo "doorgraph cells=$(find "$BASE/doorgraph_cells" -type f -name '*.lua' | wc -l)"
echo "backup=$BACK"
REMOTE_INSTALL

echo
echo "===== 7/8 VERIFY PROTECTED GLOBAL TOPOLOGY / GAME / DB ====="

GAME_SHA_AFTER="$(ssh "$DEV" "sha256sum '$GAME'" | awk '{print $1}')"
VISGRID_SHA_AFTER="$(ssh "$DEV" "sha256sum '$LIVE_LUA'" | awk '{print $1}')"
TOPO_SHA_AFTER="$(ssh "$DEV" "sha256sum '$TOPOLOGY'" | awk '{print $1}')"
DB_STAT_AFTER="$(ssh "$DEV" "stat -c '%s %Y' '$DB'")"
SHARDS_AFTER="$(ssh "$DEV" "find '$TOPOLOGY_CELLS' -type f -name '*.lua' | wc -l")"
DOOR_CELLS_AFTER="$(ssh "$DEV" "find '$BASE/doorgraph_cells' -type f -name '*.lua' | wc -l")"

VERIFY_OK=1

[ "$GAME_SHA_AFTER" = "$GAME_SHA_BEFORE" ] || VERIFY_OK=0
[ "$VISGRID_SHA_AFTER" = "$EXPECTED_V21_SHA" ] || VERIFY_OK=0
[ "$TOPO_SHA_AFTER" = "$TOPO_SHA_BEFORE" ] || VERIFY_OK=0
[ "$DB_STAT_AFTER" = "$DB_STAT_BEFORE" ] || VERIFY_OK=0
[ "$SHARDS_AFTER" -eq 1321 ] || VERIFY_OK=0
[ "$DOOR_CELLS_AFTER" -eq "$DOOR_CELLS" ] || VERIFY_OK=0

if [ "$VERIFY_OK" -ne 1 ]; then
    echo "ERROR: post-install verification failed. Rolling V21 back."
    ssh "$DEV" "STAMP='$STAMP' bash -s" <<'REMOTE_ROLLBACK'
set -e
ROOT="/mnt/SDCARD/data/ports/openmw51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
BASE="$MOD/scripts/TSPInteriorVisGrid"
BACK="$MOD/v21-backups/$STAMP"

if [ -s "$BACK/visgrid.lua.before" ]; then
    cp -pf "$BACK/visgrid.lua.before" "$BASE/visgrid.lua"
fi

rm -f "$BASE/doorgraph.lua"
if [ -s "$BACK/doorgraph.lua.before" ]; then
    cp -pf "$BACK/doorgraph.lua.before" "$BASE/doorgraph.lua"
fi

rm -rf "$BASE/doorgraph_cells"
if [ -d "$BACK/doorgraph_cells.before" ]; then
    mv "$BACK/doorgraph_cells.before" "$BASE/doorgraph_cells"
fi

rm -f "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt"
if [ -s "$BACK/REAL-DOOR-GRAPH-SUMMARY.txt.before" ]; then
    cp -pf "$BACK/REAL-DOOR-GRAPH-SUMMARY.txt.before"         "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt"
fi
sync
REMOTE_ROLLBACK
    exit 30
fi

echo "game SHA unchanged:     $GAME_SHA_AFTER"
echo "topology SHA unchanged: $TOPO_SHA_AFTER"
echo "topology shards:        $SHARDS_AFTER"
echo "DB size/mtime unchanged:$DB_STAT_AFTER"
echo "V21 sensor SHA:         $VISGRID_SHA_AFTER"
echo "doorgraph cells:        $DOOR_CELLS_AFTER"

ssh "$DEV" "
set -e
grep -q 'TSP_VISGRID_LUA_V21_DOORGRAPH_VIEWHOLD' '$LIVE_LUA'
grep -q 'TSP_VISGRID_REAL_DOOR_GRAPH_V1' '$BASE/doorgraph.lua'
echo
cat '$BASE/REAL-DOOR-GRAPH-SUMMARY.txt'
"

echo
echo "===== 8/8 WRITE V21 TRACE COLLECTOR ====="

cat > "$HOME/Downloads/pull-visgrid-v21-viewhold.sh" <<'TRACE'
#!/usr/bin/env bash
set -Eeuo pipefail
cd "$HOME/Downloads"

DEV="${TSP_DEV:-root@192.168.1.25}"
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/visgrid-v21-viewhold-$STAMP.txt"

ssh "$DEV" '
ROOT="/mnt/SDCARD/data/ports/openmw51"
BASE="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid"

echo "===== V21 INSTALL ====="
sha256sum "$BASE/visgrid.lua" 2>/dev/null || true
grep -n "TSP_VISGRID_LUA_V21_DOORGRAPH_VIEWHOLD" "$BASE/visgrid.lua" 2>/dev/null || true
echo
cat "$BASE/REAL-DOOR-GRAPH-SUMMARY.txt" 2>/dev/null || true

echo
echo "===== V21 / PVS / RAY-HOLD SESSION ====="
for LOG in \
    "$ROOT/openmw_051_log.txt" \
    "$ROOT/log-0.51.txt" \
    "$ROOT/config-0.51/openmw.log" \
    "$ROOT/config-0.51/openmw.log.old"
do
    [ -s "$LOG" ] || continue
    echo
    echo "--- $LOG ---"
    tail -n 7000 "$LOG" |
    grep -E "TSP_VISGRID_V21|TSP_VISGRID_V20|TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS|v21=1|topology sector=|context switch|PVS floor=|first_.*error| ERROR #|sensor DISABLED" \
    || true
done
' | tee "$OUT"

echo
echo "Saved:"
echo "  $OUT"
TRACE

chmod +x "$HOME/Downloads/pull-visgrid-v21-viewhold.sh"

echo
echo "=================================================================="
echo "VISGRID V21 INSTALL COMPLETE"
echo "=================================================================="
echo "V21 sensor SHA:"
echo "  $VISGRID_SHA_AFTER"
echo
echo "Global topology remained byte-identical:"
echo "  $TOPO_SHA_AFTER"
echo
echo "Restart OpenMW before testing V21."
echo
echo "For the watch-tower/opening test, watch these status fields:"
echo "  rh  = active positive-ray view holds"
echo "  rht = hold refresh/touch count"
echo "  rhc = releases after 3 close-ray confirmations"
echo "  rha = releases because the view moved away"
echo "  rhv = unverified positives rejected by exact verification"
echo "  rd  = real door refs in the current cell"
echo "  rdm = local real doors matched onto topology portals"
echo "  rdx = real WORLD_EXIT/load doors"
echo "  rdt = interior target sectors resolved from ESM destinations"
echo
echo "After testing:"
echo "  cd ~/Downloads"
echo "  ./pull-visgrid-v21-viewhold.sh"
echo
echo "Controller log:"
echo "  $LOG"
echo "=================================================================="
